using NUnit.Framework;

[TestFixture]
public class ReverseNumberTests
{
    [TestCase(1234, 4321)]
    [TestCase(1200, 21)]
    [TestCase(0, 0)]
    public void ReverseNumber_ReturnsExpected(int input, int expected)
    {
        Assert.That(ReverseNumber(input), Is.EqualTo(expected));
    }

    private int ReverseNumber(int n)
    {
        int reversed = 0;

        while (n > 0)
        {
            int digit = n % 10;
            reversed = reversed * 10 + digit;
            n /= 10;
        }

        return reversed;
    }
}
